  1→import {
  2→  ChangeDetectionStrategy,
  3→  Component,
  4→  computed,
  5→  effect,
  6→  input,
  7→  output,
  8→  signal,
  9→  untracked,
 10→} from "@angular/core";
 11→import { UpperCasePipe } from "@angular/common";
 12→import { BadgeComponent, ButtonDirective } from "@aspect/ui";
 13→import type { DecisionOption } from "../../core/decision-api.service";
 14→import { extractRecRoleId, type RoleCard } from "./role-card.types";
 15→
 16→export interface RoleCardSubmission {
 17→  roleId: string;
 18→  selectedOptions: string[];
 19→  freeText: string;
 20→}
 21→
 22→@Component({
 23→  selector: "tfc-role-card",
 24→  changeDetection: ChangeDetectionStrategy.OnPush,
 25→  imports: [UpperCasePipe, BadgeComponent, ButtonDirective],
 26→  template: `
 27→    <div class="role-card"
 28→      [class.role-card--intel]="card().status === 'intel'"
 29→      [class.role-card--active]="card().status === 'active'"
 30→      [class.role-card--done]="card().status === 'done'">
 31→
 32→      <!-- Header -->
 33→      <div class="role-card__header">
 34→        <span class="role-card__role-id">{{ card().roleId | uppercase }}</span>
 35→        <ui-badge [variant]="card().status === 'active' ? 'default' : 'secondary'">
 36→          {{ badgeLabel() }}
 37→        </ui-badge>
 38→      </div>
 39→      <div class="role-card__role-label">{{ card().roleLabel }}</div>
 40→
 41→      <!-- Intel -->
 42→      @if (card().intel) {
 43→        <div class="role-card__intel">{{ card().intel }}</div>
 44→      } @else if (card().decision) {
 45→        <div class="role-card__intel role-card__intel--empty">No role-specific intel this turn</div>
 46→      }
 47→
 48→      <!-- Advisor Recs (CO card only) -->
 49→      @if (card().advisorRecs.length > 0) {
 50→        <div class="role-card__recs">
 51→          <div class="role-card__recs-title">Advisor Recommendations</div>
 52→          @for (rec of card().advisorRecs; track rec.roleId) {
 53→            <div class="role-card__rec" [class.role-card__rec--pending]="!rec.selection">
 54→              <span class="role-card__rec-role">{{ rec.roleLabel }}:</span>
 55→              @if (rec.selection) {
 56→                <span class="role-card__rec-selection">{{ rec.selection }}</span>
 57→              } @else {
 58→                <span class="role-card__rec-pending">pending...</span>
 59→              }
 60→            </div>
 61→          }
 62→        </div>
 63→      }
 64→
 65→      <!-- Decision Form (active only) -->
 66→      @if (card().decision && card().status === 'active') {
 67→        <div class="role-card__decision">
 68→          <div class="role-card__decision-question">{{ card().decision!.description }}</div>
 69→          @if (questionType() === 'single_choice' || questionType() === 'multi_choice') {
 70→            @for (option of filteredOptions(); track option.id) {
 71→              <label class="role-card__option" [class.role-card__option--selected]="isSelected(option.id)">
 72→                <input
 73→                  [type]="questionType() === 'single_choice' ? 'radio' : 'checkbox'"
 74→                  [name]="'role-decision-' + card().roleId"
 75→                  [checked]="isSelected(option.id)"
 76→                  (change)="toggleOption(option)"
 77→                />
 78→                <span>{{ option.label }}</span>
 79→              </label>
 80→            }
 81→          }
 82→          @if (questionType() === 'free_text') {
 83→            <textarea class="role-card__textarea"
 84→              [value]="freeText()"
 85→              (input)="onTextInput($event)"
 86→              placeholder="Enter your response..."></textarea>
 87→          }
 88→          <div class="role-card__actions">
 89→            <button uiButton variant="default" size="sm" (click)="onSubmit()" [disabled]="!canSubmit()">
 90→              Submit
 91→            </button>
 92→          </div>
 93→        </div>
 94→      }
 95→
 96→      <!-- Done State -->
 97→      @if (card().status === 'done') {
 98→        <div class="role-card__done">Selected: {{ doneLabel() }}</div>
 99→      }
100→    </div>
101→  `,
102→})
103→export class RoleCardComponent {
104→  readonly card = input.required<RoleCard>();
105→  readonly submitted = output<RoleCardSubmission>();
106→
107→  readonly selectedOptions = signal<string[]>([]);
108→  readonly freeText = signal("");
109→
110→  private readonly resetOnCardChange = effect(() => {
111→    this.card();
112→    untracked(() => {
113→      this.selectedOptions.set([]);
114→      this.freeText.set("");
115→    });
116→  });
117→
118→  readonly filteredOptions = computed<DecisionOption[]>(() => {
119→    const decision = this.card().decision;
120→    if (!decision) return [];
121→    const playerType = this.card().playerType;
122→    const roleId = this.card().roleId;
123→    if (playerType === "decision_maker") {
124→      return decision.options;
125→    }
126→    // advisor: COMMON options (no role) + own-role options
127→    return decision.options.filter(
128→      (o) => !o.role || o.role === roleId,
129→    );
130→  });
131→
132→  readonly badgeLabel = computed<string>(() => {
133→    const status = this.card().status;
134→    if (status === "intel") return "INTEL";
135→    if (status === "active") return "DECISION";
136→    return "DONE";
137→  });
138→
139→  readonly questionType = computed<string>(() => {
140→    return this.card().decision?.question_type ?? "free_text";
141→  });
142→
143→  readonly doneLabel = computed<string>(() => {
144→    const decision = this.card().decision;
145→    if (!decision) return "";
146→    const roleId = this.card().roleId;
147→    const recEntry = Object.entries(decision.recommendations).find(
148→      ([key]) => extractRecRoleId(key) === roleId,
149→    );
150→    const optionId = recEntry?.[1];
151→    if (!optionId) return "";
152→    return decision.options.find((o) => o.id === optionId)?.label ?? optionId;
153→  });
154→
155→  protected isSelected(optionId: string): boolean {
156→    return this.selectedOptions().includes(optionId);
157→  }
158→
159→  protected canSubmit(): boolean {
160→    if (this.questionType() === "free_text") {
161→      return this.freeText().trim().length > 0;
162→    }
163→    return this.selectedOptions().length > 0;
164→  }
165→
166→  protected toggleOption(option: DecisionOption): void {
167→    if (this.questionType() === "single_choice") {
168→      this.selectedOptions.set([option.id]);
169→    } else {
170→      const current = this.selectedOptions();
171→      if (current.includes(option.id)) {
172→        this.selectedOptions.set(current.filter((id) => id !== option.id));
173→      } else {
174→        this.selectedOptions.set([...current, option.id]);
175→      }
